package com.Rouxin.ShellTool

import android.util.Base64
import java.io.File

object RxinSandbox {

    private var initialized = false


    @JvmStatic fun getPathFragment(): String {
        return getHome() + "/bin"
    }

    @JvmStatic fun getHome(): String {
        return "/data/data/com.Rouxin.ShellTool/RXin"
    }

    @JvmStatic fun getShinitPath(): String {
        return "/data/data/com.Rouxin.ShellTool/RXin/.shinit"
    }

    @JvmStatic fun createSandbox() {
        if (initialized) return
        initialized = true

        val home = getHome()
        val binDir = "$home/bin"

        createViaFileApi(home, binDir)
    }

    private fun createViaFileApi(home: String, binDir: String) {
        File(binDir).mkdirs()
        File("$home/lib").mkdirs()
        File("$home/etc").mkdirs()
        File("$home/share").mkdirs()

        decodeToFile(File(binDir), "engine", SCRIPT__ENGINE)
        decodeToFile(File(binDir), "fortune", SCRIPT__FORTUNE)
        decodeToFile(File(binDir), "hello", SCRIPT__HELLO)
        decodeToFile(File(binDir), "nyan", SCRIPT__NYAN)
        decodeToFile(File(binDir), "rr", SCRIPT__RR)
        decodeToFile(File(binDir), "rxe", SCRIPT__RXE)
        decodeToFile(File(binDir), "snow", SCRIPT__SNOW)
        decodeToFile(File(binDir), "Xie", SCRIPT__XIE)

        decodeToFile(File(home), ".shinit", SCRIPT__SHINIT)

        File(binDir).listFiles()?.forEach { file ->
            if (file.isFile) file.setExecutable(true, false)
        }
    }

    private fun decodeToFile(dir: File, name: String, base64: String) {
        val file = File(dir, name)
        val data = Base64.decode(base64, Base64.DEFAULT)
        val content = String(data, Charsets.UTF_8)
        if (file.exists() && file.readText() == content) return
        file.writeText(content)
    }


    private val SCRIPT__ENGINE = ""
    private val SCRIPT__FORTUNE = ""
    private val SCRIPT__HELLO = ""
    private val SCRIPT__NYAN = ""
    private val SCRIPT__RR = ""
    private val SCRIPT__RXE = ""
    private val SCRIPT__SNOW = ""
    private val SCRIPT__XIE = ""
    private val SCRIPT__SHINIT = ""
}